        ?quantityValue a qudt:QuantityValue ;
                       qudt:numericValue ?value ;
                       qudt:unit <http://qudt.org/vocab/unit/MilliM> .
        FILTER(?time >= "2002-01-01T00:00:00"^^xsd:dateTime && ?time < "2006-01-01T00:00:00"^^xsd:dateTime)
        BIND(YEAR(?time) AS ?year)
      }
    }
    GROUP BY ?year
  }
}

